    const toDet = DETECTOR_POS.clone().sub(exitPt);
    const t = toDet.dot(DETECTOR_NORMAL) / denom;
    if (t > 0 && t < 4.0) {
      tailLen = t;
    }
  }
  pts.push(exitPt.clone().add(exitDir.clone().multiplyScalar(tailLen)));
  return pts;
}

