}

function updatePaths() {
  let minDist = Infinity;
  let bestIdx = 0;
  for (let i = 0; i < 5; i++) {
    const pts = computePathPoints(isotopes[i].mass, currentB);
    if (!pts) { pathLines[i].visible = false; continue; }
    pathLines[i].visible = true;
    const old = pathLines[i].geometry;
    pathLines[i].geometry = new THREE.BufferGeometry().setFromPoints(pts);
    old?.dispose();
    const endPt = pts[pts.length - 1];
    const dist = endPt.distanceTo(DETECTOR_POS);
    if (dist < minDist) { minDist = dist; bestIdx = i; }
  }
  detectedIndex = bestIdx;
  for (let i = 0; i < 5; i++) {
    if (i === detectedIndex) {
      pathMats[i].color.setHex(0x00e6b8);
    } else {
      pathMats[i].color.setHex(0x1fb0c0);
