<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// === ELEMENT SPEC ===
// sample inlet → CylinderGeometry(0.08,0.08,0.5) grey #999, at (-3.5,0,0) rotZ 90°
// chamber cap → SphereGeometry(0.55) half, at (-3,0,0)
// main tube → CylinderGeometry(0.55,0.55,4,32,1,true) translucent #ccc op0.25, center (-1,0,0) rotZ 90°
// heater coil → TubeGeometry helix, #cc4422, near (-2.4,0.3,0)
// electron source → BoxGeometry(0.15,0.35,0.15) #555 at (-2.4,-0.9,0)
// electron rays → 5 Lines #ffcc00 fan upward from source
// ion cloud → 8 SphereGeometry(0.04) #2bb3b3 near (-2.0,0,0)
// lens1 → RingGeometry(0.12,0.55,32) #9999cc at (-1.2,0,0) rotY 90°
// lens2 → RingGeometry(0.12,0.55,32) #9999cc at (-0.4,0,0) rotY 90°
// magnet top → CylinderGeometry(0.7,0.7,1.3,32) #b0b0b0, axis tilted 45° (along (0.707,0.707,0)), center ~(2.2,1.0,0)
// magnet bottom → CylinderGeometry(0.7,0.7,1.3,32) #b0b0b0, axis tilted 45°, center ~(0.2,-1.0,0)
// field slab → BoxGeometry(1.2,2.2,1.4) #aa88cc op0.3, rotated 45° around Z at (1.2,0,0)
// detector tube → CylinderGeometry(0.5,0.5,len,32,1,true) translucent, from (1.2,0,0) to (3.2,-2,0)
// detector disc → CircleGeometry(0.48,32) #cfe6a0 at (3.2,-2,0)
// ion paths → 5 Lines #1fb0c0, straight+arc+tail clipped at detector
// leader lines → thin black Lines from labels to components
// spectrum: axes, gridlines, 5 bars, labels (positioned right in combined)

const isotopes = [
  { mass: 90, abundance: 51.45, label: 'Zr-90' },
  { mass: 91, abundance: 11.22, label: 'Zr-91' },
  { mass: 92, abundance: 17.15, label: 'Zr-92' },
  { mass: 94, abundance: 17.38, label: 'Zr-94' },
  { mass: 96, abundance: 2.80, label: 'Zr-96' }
];

let currentB = 0.6;
let viewMode = 'Instrument';
let detectedIndex = 0;
let selectedIsotope = -1;

// ── Instrument Group ──
const instrumentGroup = new THREE.Group();
scene.add(instrumentGroup);

// Main tube
const tubeMat = new THREE.MeshBasicMaterial({ color: 0xcccccc, transparent: true, opacity: 0.25, side: THREE.DoubleSide });
const tubeGeom = new THREE.CylinderGeometry(0.55, 0.55, 4, 32, 1, true);
const tube = new THREE.Mesh(tubeGeom, tubeMat);
tube.rotation.z = Math.PI / 2;
tube.position.set(-1, 0, 0);
instrumentGroup.add(tube);

// Chamber cap (hemisphere at left end)
const capGeom = new THREE.SphereGeometry(0.55, 32, 16, 0, Math.PI * 2, 0, Math.PI / 2);
const cap = new THREE.Mesh(capGeom, tubeMat.clone());
cap.rotation.z = Math.PI / 2;
cap.position.set(-3, 0, 0);
instrumentGroup.add(cap);

// Sample inlet
const inletGeom = new THREE.CylinderGeometry(0.08, 0.08, 0.5, 16);
const inletMat = new THREE.MeshBasicMaterial({ color: 0x999999 });
const inlet = new THREE.Mesh(inletGeom, inletMat);
inlet.rotation.z = Math.PI / 2;
inlet.position.set(-3.5, 0, 0);
instrumentGroup.add(inlet);

// Heater coil (helix)
const helixPts = [];
const helixTurns = 6;
const helixRadius = 0.12;
const helixLength = 0.6;
for (let i = 0; i <= helixTurns * 32; i++) {
  const t = i / (helixTurns * 32);
  const angle = t * helixTurns * Math.PI * 2;
  helixPts.push(new THREE.Vector3(
    -2.7 + t * helixLength,
    0.3 + helixRadius * Math.sin(angle),
    helixRadius * Math.cos(angle)
  ));
}
const helixCurve = new THREE.CatmullRomCurve3(helixPts);
const helixGeom = new THREE.TubeGeometry(helixCurve, 200, 0.02, 8, false);
const helixMat = new THREE.MeshBasicMaterial({ color: 0xcc4422 });
const heater = new THREE.Mesh(helixGeom, helixMat);
instrumentGroup.add(heater);

// Electron beam source
const srcGeom = new THREE.BoxGeometry(0.15, 0.35, 0.15);
const srcMat = new THREE.MeshBasicMaterial({ color: 0x555555 });
const eSource = new THREE.Mesh(srcGeom, srcMat);
eSource.position.set(-2.4, -0.9, 0);
instrumentGroup.add(eSource);

// Electron rays (fan)
const rayMat = new THREE.LineBasicMaterial({ color: 0xffcc00 });
for (let i = 0; i < 5; i++) {
  const angle = (i - 2) * 0.15;
  const pts = [
    new THREE.Vector3(-2.4, -0.7, 0),
    new THREE.Vector3(-2.4 + Math.sin(angle) * 0.5, -0.7 + Math.cos(angle) * 0.5, 0)
  ];
  const rayGeom = new THREE.BufferGeometry().setFromPoints(pts);
  instrumentGroup.add(new THREE.Line(rayGeom, rayMat));
}

// Ion cloud
const cloudMat = new THREE.MeshBasicMaterial({ color: 0x2bb3b3 });
for (let i = 0; i < 8; i++) {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.04, 8, 8), cloudMat);
  s.position.set(-2.0 + (Math.random() - 0.5) * 0.3, (Math.random() - 0.5) * 0.2, (Math.random() - 0.5) * 0.2);
  instrumentGroup.add(s);
}

// Acceleration lenses
const lensMat = new THREE.MeshBasicMaterial({ color: 0x9999cc, transparent: true, opacity: 0.5, side: THREE.DoubleSide });
const lens1 = new THREE.Mesh(new THREE.RingGeometry(0.12, 0.55, 32), lensMat);
lens1.rotation.y = Math.PI / 2;
lens1.position.set(-1.2, 0, 0);
instrumentGroup.add(lens1);
const lens2 = new THREE.Mesh(new THREE.RingGeometry(0.12, 0.55, 32), lensMat.clone());
lens2.rotation.y = Math.PI / 2;
lens2.position.set(-0.4, 0, 0);
instrumentGroup.add(lens2);

// Magnet poles — tilted 45° to match detector tube angle
// Detector tube direction: (2,-2,0) normalized = (0.707,-0.707,0)
// Magnet axis perpendicular to detector: (0.707, 0.707, 0)
const magAxisDir = new THREE.Vector3(0.707, 0.707, 0).normalize();
const magMat = new THREE.MeshBasicMaterial({ color: 0xb0b0b0 });

const magTop = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.7, 1.3, 32), magMat);
// Position top pole: bend point + axis * 1.4
magTop.position.set(1.2 + magAxisDir.x * 1.4, magAxisDir.y * 1.4, 0);
// Rotate cylinder axis from Y to magAxisDir
magTop.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), magAxisDir);
instrumentGroup.add(magTop);

const magBot = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.7, 1.3, 32), magMat.clone());
magBot.position.set(1.2 - magAxisDir.x * 1.4, -magAxisDir.y * 1.4, 0);
magBot.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), magAxisDir);
instrumentGroup.add(magBot);

// Field slab — rotated 45° to match tilted magnet poles
const slabMat = new THREE.MeshBasicMaterial({ color: 0xaa88cc, transparent: true, opacity: 0.3, side: THREE.DoubleSide });
const slab = new THREE.Mesh(new THREE.BoxGeometry(1.2, 2.2, 1.4), slabMat);
slab.position.set(1.2, 0, 0);
slab.rotation.z = -Math.PI / 4; // rotate to align with detector tube direction
instrumentGroup.add(slab);

// Detector tube
const detTubeDir = new THREE.Vector3(3.2 - 1.2, -2.0 - 0, 0).normalize();
const detTubeLen = new THREE.Vector3(3.2 - 1.2, -2.0, 0).length();
const detTubeGeom = new THREE.CylinderGeometry(0.5, 0.5, detTubeLen, 32, 1, true);
const detTube = new THREE.Mesh(detTubeGeom, tubeMat.clone());
detTube.position.set((1.2 + 3.2) / 2, -1.0, 0);
detTube.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), detTubeDir);
instrumentGroup.add(detTube);

// Detector disc
const detDiscGeom = new THREE.CircleGeometry(0.48, 32);
const detDiscMat = new THREE.MeshBasicMaterial({ color: 0xcfe6a0, side: THREE.DoubleSide });
const detDisc = new THREE.Mesh(detDiscGeom, detDiscMat);
detDisc.position.set(3.2, -2.0, 0);
detDisc.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), detTubeDir);
instrumentGroup.add(detDisc);

// ── Ion Paths ──
const pathLines = [];
const pathMats = [];
const ENTRY_X = 0.8;
const DETECTOR_POS = new THREE.Vector3(3.2, -2.0, 0);
const DETECTOR_NORMAL = detTubeDir.clone();
const SWEEP_ANGLE = Math.PI / 4;
const R_PERFECT = 0.97;
const SPREAD = 0.15;

function detectedMass(B) {
  return 90 + (B - 0.6) * (6 / 0.7);
}

function computePathPoints(mass, B) {
  const dm = detectedMass(B);
  const r = R_PERFECT + SPREAD * (mass - dm);
  if (r < 0.3) return null;
  const pts = [];
  pts.push(new THREE.Vector3(-2, 0, 0));
  pts.push(new THREE.Vector3(ENTRY_X, 0, 0));
  const nArc = 30;
  for (let i = 1; i <= nArc; i++) {
    const theta = (i / nArc) * SWEEP_ANGLE;
    pts.push(new THREE.Vector3(
      ENTRY_X + r * Math.sin(theta),
      -r + r * Math.cos(theta),
      0
    ));
  }
  const exitDir = new THREE.Vector3(Math.cos(SWEEP_ANGLE), -Math.sin(SWEEP_ANGLE), 0).normalize();
  const exitPt = pts[pts.length - 1].clone();
  const denom = exitDir.dot(DETECTOR_NORMAL);
  let tailLen = 2.0;
  if (Math.abs(denom) > 0.001) {
    const toDet = DETECTOR_POS.clone().sub(exitPt);
    const t = toDet.dot(DETECTOR_NORMAL) / denom;
    if (t > 0 && t < 4.0) tailLen = t;
  }
  pts.push(exitPt.clone().add(exitDir.clone().multiplyScalar(tailLen)));
  return pts;
}

for (let i = 0; i < 5; i++) {
  const mat = new THREE.LineBasicMaterial({ color: 0x1fb0c0 });
  const line = new THREE.Line(new THREE.BufferGeometry(), mat);
  instrumentGroup.add(line);
  pathLines.push(line);
  pathMats.push(mat);
}

function updatePaths() {
  let minDist = Infinity;
  let bestIdx = 0;
  for (let i = 0; i < 5; i++) {
    const pts = computePathPoints(isotopes[i].mass, currentB);
    if (!pts) { pathLines[i].visible = false; continue; }
    pathLines[i].visible = true;
    const old = pathLines[i].geometry;
    pathLines[i].geometry = new THREE.BufferGeometry().setFromPoints(pts);
    old?.dispose();
    const endPt = pts[pts.length - 1];
    const dist = endPt.distanceTo(DETECTOR_POS);
    if (dist < minDist) { minDist = dist; bestIdx = i; }
  }
  detectedIndex = bestIdx;
  for (let i = 0; i < 5; i++) {
    if (i === detectedIndex) {
      pathMats[i].color.setHex(0x00e6b8);
    } else {
      pathMats[i].color.setHex(0x1fb0c0);
    }
  }
  updateBarHighlights();
}

// ── Leader Lines ──
const leaderMat = new THREE.LineBasicMaterial({ color: 0x000000 });
function addLeader(from, to) {
  const pts = [new THREE.Vector3(from[0], from[1], 0), new THREE.Vector3(to[0], to[1], 0)];
  const geom = new THREE.BufferGeometry().setFromPoints(pts);
  instrumentGroup.add(new THREE.Line(geom, leaderMat));
}

addLeader([-3.5, 1.0], [-3.5, 0.35]);
addLeader([-2.2, 1.0], [-2.4, 0.55]);
addLeader([-2.4, -1.5], [-2.4, -1.1]);
addLeader([-0.8, -0.95], [-0.8, -0.35]);
addLeader([2.2, 2.3], [2.2, 1.7]);
addLeader([1.6, -2.6], [1.6, -1.2]);
addLeader([3.2, -2.55], [3.2, -2.15]);

// ── Spectrum Group ──
const spectrumGroup = new THREE.Group();
scene.add(spectrumGroup);
spectrumGroup.visible = false; // FIX: hidden at startup

const specWidth = 4;
const specHeight = 3;
const xMin = 89, xMax = 97;

function specX(mz) { return (mz - xMin) / (xMax - xMin) * specWidth; }
function specY(pct) { return (pct / 100) * specHeight; }

// Axes
const axisMat = new THREE.LineBasicMaterial({ color: 0x000000 });
const xAxisPts = [new THREE.Vector3(0, 0, 0), new THREE.Vector3(specWidth, 0, 0)];
spectrumGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(xAxisPts), axisMat));
const yAxisPts = [new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, specHeight, 0)];
spectrumGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(yAxisPts), axisMat));

// Gridlines
const gridMat = new THREE.LineBasicMaterial({ color: 0xdddddd });
for (let pct = 25; pct <= 100; pct += 25) {
  const y = specY(pct);
  const gPts = [new THREE.Vector3(0, y, 0), new THREE.Vector3(specWidth, y, 0)];
  spectrumGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(gPts), gridMat));
}

// Tick marks on x-axis
const tickMat = new THREE.LineBasicMaterial({ color: 0x000000 });
for (let mz = 90; mz <= 96; mz += 2) {
  const x = specX(mz);
  const tPts = [new THREE.Vector3(x, -0.08, 0), new THREE.Vector3(x, 0.08, 0)];
  spectrumGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(tPts), tickMat));
}

// Y-axis ticks
for (let pct = 0; pct <= 100; pct += 50) {
  const y = specY(pct);
  const tPts = [new THREE.Vector3(-0.08, y, 0), new THREE.Vector3(0.08, y, 0)];
  spectrumGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(tPts), tickMat));
}

// Bars
const barMeshes = [];
const barMats = [];
const barWidth = 0.25;
for (let i = 0; i < 5; i++) {
  const h = specY(isotopes[i].abundance);
  const mat = new THREE.MeshBasicMaterial({ color: 0x2bb3b3 });
  const bar = new THREE.Mesh(new THREE.BoxGeometry(barWidth, h, 0.05), mat);
  bar.position.set(specX(isotopes[i].mass), h / 2, 0);
  spectrumGroup.add(bar);
  barMeshes.push(bar);
  barMats.push(mat);
  registerInteractive(bar, {
    title: isotopes[i].label,
    body: `Mass-to-charge ratio: ${isotopes[i].mass}\nRelative abundance: ${isotopes[i].abundance}%`,
    tooltip: `Click to highlight ${isotopes[i].label}`,
    onClick: () => { selectedIsotope = i; updateBarHighlights(); }
  });
}

function updateBarHighlights() {
  for (let i = 0; i < 5; i++) {
    if (i === detectedIndex || i === selectedIsotope) {
      barMats[i].color.setHex(0x00ccaa);
    } else {
      barMats[i].color.setHex(0x2bb3b3);
    }
  }
}

// ── Labels ──
addLabel('Sample<br>enters<br>here', new THREE.Vector3(-3.5, 1.3, 0), { fontSize: '13px', bold: true });
addLabel('Heater vaporizes<br>sample', new THREE.Vector3(-2.0, 1.3, 0), { fontSize: '13px', bold: true });
addLabel('Electron beam<br>source', new THREE.Vector3(-2.4, -1.8, 0), { fontSize: '13px', bold: true });
