    { viewMode: 'Spectrum', fieldStrength: 1.2 },
    { viewMode: 'Combined', fieldStrength: 0.9 }
  ];
  const s = steps[stepIdx];
  if (!s) return;
  currentB = s.fieldStrength;
  sliderB.value = currentB;
  valB.textContent = currentB.toFixed(2);
  setViewMode(s.viewMode);
  updatePaths();
};

